package sniff

import (
	"encoding/hex"
	"testing"
)

// Captured TLS ClientHello with SNI "example.com" (Go crypto/tls client).
const tlsClientHelloExampleCom = ""

func TestSniffTLS(t *testing.T) {
	data, err := hex.DecodeString(tlsClientHelloExampleCom)
	if err != nil {
		t.Fatal(err)
	}
	sni := SniffTLS(data)
	if sni != "example.com" {
		t.Fatalf("expected SNI 'example.com', got %q", sni)
	}
}

func TestSniffTLS_NoSNI(t *testing.T) {
	// Too short to be a valid ClientHello
	sni := SniffTLS([]byte{0x16, 0x03, 0x01})
	if sni != "" {
		t.Fatalf("expected empty SNI for truncated data, got %q", sni)
	}
}

func TestSniffTLS_NotTLS(t *testing.T) {
	// Random bytes that aren't TLS
	sni := SniffTLS([]byte("Hello, this is not TLS data at all"))
	if sni != "" {
		t.Fatalf("expected empty SNI for non-TLS data, got %q", sni)
	}
}

func TestSniffTLS_Empty(t *testing.T) {
	sni := SniffTLS(nil)
	if sni != "" {
		t.Fatalf("expected empty SNI for nil data, got %q", sni)
	}
}
